"""Convert inbound A2A message slot payloads into Rasa `SetSlotCommand`."""

from __future__ import annotations

import json
import re
from typing import TYPE_CHECKING, Any

import structlog
from a2a.types import Message

from rasa.dialogue_understanding.commands.set_slot_command import SetSlotCommand
from rasa.shared.core.constants import SLOTS_EXCLUDED_FOR_AGENT, SetSlotExtractor
from rasa.shared.core.slots import InvalidSlotValueError

if TYPE_CHECKING:
    from rasa.shared.core.domain import Domain

structlogger = structlog.get_logger()

_METADATA_SLOTS_KEY = "slots"
_NULL_VALUE_STRINGS = frozenset({"none", "null", "undefined"})
_SLOTS_LINE_PATTERN = re.compile(r"^SLOTS:\s*(\{[^\}]*\})\s*$", re.MULTILINE)
_JSON_FENCE_PATTERN = re.compile(
    r"```json\s*(\{[^\}]*\})\s*```\s*$", re.DOTALL | re.IGNORECASE
)


class A2AMessageAdapter:
    """Extract orchestrator slot context from A2A messages for the command pipeline."""

    def __init__(self, domain: Domain) -> None:
        self._slots_by_name = {slot.name: slot for slot in domain.slots}

    def extract_slot_values(
        self,
        message: Message | None,
        user_text: str,
        metadata: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Return domain-defined, coerced slot values from all supported sources."""
        merged: dict[str, Any] = {}
        merged.update(self._slots_from_transcript(user_text))
        merged.update(self._slots_from_metadata(metadata))
        merged.update(self._slots_from_message_parts(message))
        return self._filter_and_coerce(merged)

    def strip_slot_markers_from_text(self, user_text: str) -> str:
        """Remove embedded slots so they are not sent to the LLM as user text."""
        if not user_text:
            return user_text
        stripped = _JSON_FENCE_PATTERN.sub("", user_text).strip()
        stripped = _SLOTS_LINE_PATTERN.sub("", stripped).strip()
        return stripped

    def to_set_slot_commands(self, slot_values: dict[str, Any]) -> list[SetSlotCommand]:
        """Build ``SetSlotCommand`` instances for the command pipeline."""
        return [
            SetSlotCommand(
                name=name,
                value=value,
                extractor=SetSlotExtractor.A2A_CLIENT.value,
            )
            for name, value in slot_values.items()
        ]

    def _slots_from_metadata(self, metadata: dict[str, Any] | None) -> dict[str, Any]:
        if not metadata:
            return {}
        raw = metadata.get(_METADATA_SLOTS_KEY)
        if not isinstance(raw, dict):
            return {}
        return {str(key): value for key, value in raw.items()}

    def _slots_from_message_parts(self, message: Message | None) -> dict[str, Any]:
        if message is None:
            return {}
        merged: dict[str, Any] = {}
        for part in message.parts:
            root = part.root
            if getattr(root, "kind", None) != "data":
                continue
            data = getattr(root, "data", None)
            if not isinstance(data, dict):
                continue
            raw_slots = data.get(_METADATA_SLOTS_KEY)
            if isinstance(raw_slots, dict):
                merged.update({str(key): value for key, value in raw_slots.items()})
        return merged

    def _slots_from_transcript(self, user_text: str) -> dict[str, Any]:
        if not user_text:
            return {}
        for pattern in (_JSON_FENCE_PATTERN, _SLOTS_LINE_PATTERN):
            match = pattern.search(user_text)
            if match is None:
                continue
            parsed = _parse_slots_json(match.group(1))
            if parsed:
                return parsed
        return {}

    def _filter_and_coerce(self, raw_slots: dict[str, Any]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for name, value in raw_slots.items():
            if not self._is_writable_slot(name):
                structlogger.debug(
                    "a2a_server.message_adapter.skip_slot",
                    slot_name=name,
                    reason="not_in_domain_or_excluded",
                )
                continue
            slot = self._slots_by_name[name]
            normalized = _normalize_nullable_value(value)
            try:
                coerced = slot.coerce_value(normalized)
            except InvalidSlotValueError:
                structlogger.warning(
                    "a2a_server.message_adapter.skip_slot.invalid_value",
                    slot_name=name,
                )
                continue
            if not slot.is_valid_value(coerced):
                structlogger.warning(
                    "a2a_server.message_adapter.skip_slot.invalid_value",
                    slot_name=name,
                )
                continue
            result[name] = coerced
        return result

    def _is_writable_slot(self, name: str) -> bool:
        slot = self._slots_by_name.get(name)
        if slot is None:
            return False
        if name in SLOTS_EXCLUDED_FOR_AGENT:
            return False
        return not slot.is_builtin


def _normalize_nullable_value(value: Any) -> Any:
    if isinstance(value, str) and value.lower() in _NULL_VALUE_STRINGS:
        return None
    return value


def _parse_slots_json(payload: str) -> dict[str, Any]:
    try:
        parsed = json.loads(payload)
    except json.JSONDecodeError:
        structlogger.debug(
            "a2a_server.message_adapter.skip_transcript_slots.invalid_json",
            payload=payload,
        )
        return {}
    if not isinstance(parsed, dict):
        structlogger.debug(
            "a2a_server.message_adapter.skip_transcript_slots.not_object",
            payload=payload,
        )
        return {}
    return {str(key): value for key, value in parsed.items()}
